import React from 'react';
import Chatbot from './Chatbot';

export default function Home(){
  return (
    <div>
      <header className="hero">
        <img src="https://images.unsplash.com/photo-1520975698510-1b87d8a67a8a?q=80&w=1400&auto=format&fit=crop&ixlib=rb-4.0.3&s=9a5b0b2a8d6d4f9fb0d3f2e6a6a3b1e6" alt="hero" />
        <h1>Welcome to our NGO Portal</h1>
        <p>Join, volunteer, donate and make a difference.</p>
      </header>
      <section className="content">
        <h2>Featured Initiatives</h2>
        <div className="cards">
          <div className="card"><img src="https://tse4.mm.bing.net/th/id/OIP.LVm5csYzP0walaiBMfK-XwHaE8?pid=Api&P=0&h=180" alt="a" /><h3>Community Cleanup</h3></div>
          <div className="card"><img src="https://tse1.mm.bing.net/th/id/OIP.1jZ3JoJQTBNLnLJKSIHIbwHaC9?pid=Api&P=0&h=180" alt="b" /><h3>Food Drive</h3></div>
          <div className="card"><img src="https://tse1.mm.bing.net/th/id/OIP.0x9LG00FrxuQflQMcyFpJAHaE7?pid=Api&P=0&h=180" alt="c" /><h3>Education Support</h3></div>
        </div>
      </section>
      <Chatbot />
    </div>
  );
}
